<script setup lang="ts">
import { t } from '@/i18n';
import { computed, ref } from 'vue'; import { useRouter } from 'vue-router'; import { api } from '@/app/runtime'; import { useAsync } from '@/composables/useAsync'; import type { JsonObject } from '@/api/types';
const router = useRouter(); const keyword = ref(''); const query = useAsync<JsonObject[]>(); const results = computed(() => query.data.value ?? []);
async function search() { if (!keyword.value.trim()) return; await query.run(() => api.search(keyword.value.trim())); }
</script>
<template><section class="page"><button class="text-action" @click="router.back()">{{ t('s_omytgn') }}</button><h1>{{ t('s_367f3v') }}</h1><form class="form" @submit.prevent="search"><input v-model="keyword" :placeholder="t('s_crhxaz')" :aria-label="t('s_1j51671')"><button class="cta">{{ t('s_367f3v') }}</button></form><div v-if="query.loading.value" class="state">{{ t('s_5vti32') }}</div><p v-else-if="query.error.value" class="state error">{{ query.error.value?.message }}</p><div v-else class="list"><button v-for="item in results" :key="String(item.id || item.nickname || item.title)" class="row-card" @click="item.id ? router.push(`/detail/${item.id}`) : undefined"><strong>{{ item.title || item.nickname }}</strong><span>{{ item.venue || item.bio || item.category }}</span></button><p v-if="keyword && results.length === 0" class="state">{{ t('s_k2gqbq') }}</p></div></section></template>
